    D=[(0,1),(0,-1),(1,0),(-1,0)]
    for i in range(HH):
        for j in range(WW):
            if g[i][j]==v and (i,j) not in seen:
                st=[(i,j)];c=[]
                while st:
                    p=st.pop()
                    if p in seen: continue
                    seen.add(p); c.append(p)
                    for dd_ in D:
                        n=(p[0]+dd_[0],p[1]+dd_[1])
                        if 0<=n[0]<HH and 0<=n[1]<WW and g[n[0]][n[1]]==v and n not in seen:
                            st.append(n)
                res.append(c)
    return res
